'use strict';

const appRoot = document.getElementById('app');
const navigation = document.getElementById('navigation');
const deleteDialog = document.getElementById('confirm-dialog');
const confirmDeleteButton = document.getElementById('confirm-delete');
let currentUser = null;

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[character]);
}

function formatDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat(undefined, {
    year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'
  }).format(date);
}

function codePointLength(value) {
  return Array.from(value).length;
}

function dateLabel(post) {
  const updated = post.modifiedAt && post.createdAt &&
    new Date(post.modifiedAt).getTime() > new Date(post.createdAt).getTime();
  return `${updated ? 'Updated' : 'Published'} ${formatDate(updated ? post.modifiedAt : post.createdAt)}`;
}

async function api(url, options = {}) {
  const headers = new Headers(options.headers || {});
  headers.set('X-Requested-With', 'XMLHttpRequest');
  if (options.body !== undefined) headers.set('Content-Type', 'application/json');
  const response = await fetch(url, { ...options, headers, credentials: 'same-origin' });
  if (response.status === 204) return null;
  let data;
  try { data = await response.json(); } catch { data = { error: 'The server returned an unreadable response.' }; }
  if (!response.ok) {
    const error = new Error(data.error || 'Request failed.');
    error.status = response.status;
    error.fields = data.fields || {};
    throw error;
  }
  return data;
}

function showError(container, message) {
  let element = container.querySelector('.form-error');
  if (!element) {
    element = document.createElement('p');
    element.className = 'form-error';
    element.setAttribute('role', 'alert');
    container.prepend(element);
  }
  element.textContent = message;
}

function clearError(container) {
  const element = container.querySelector('.form-error');
  if (element) element.remove();
  container.querySelectorAll('.field-error').forEach(node => node.remove());
}

function applyFieldErrors(form, fields) {
  for (const [field, message] of Object.entries(fields)) {
    const input = form.elements.namedItem(field);
    if (!input) continue;
    const error = document.createElement('small');
    error.className = 'field-error';
    error.textContent = message;
    input.insertAdjacentElement('afterend', error);
    input.setAttribute('aria-invalid', 'true');
  }
}

function updateNavigation() {
  if (currentUser) {
    navigation.innerHTML = `
      <a href="/">Home</a><a href="/posts/new">Write</a>
      <span class="nav-user">${escapeHtml(currentUser.username)}</span>
      <button class="nav-button" id="logout-button" type="button">Log out</button>`;
    document.getElementById('logout-button').addEventListener('click', async () => {
      try {
        await api('/api/auth/logout', { method: 'POST' });
      } catch (error) {
        if (error.status !== 401) {
          alert(error.message);
          return;
        }
      }
      currentUser = null;
      window.location.assign('/login');
    });
  } else {
    navigation.innerHTML = '<a href="/">Home</a><a href="/login">Log in</a><a href="/register">Register</a>';
  }
}

function renderHome() {
  appRoot.innerHTML = `
    <section class="home-intro">
      <p class="eyebrow">Notes from the community</p>
      <h1>A little space<br>to share a thought.</h1>
      <p class="intro-copy">Small observations, careful words, and ideas worth sitting with.</p>
    </section>
    <section aria-label="Browse posts">
      <div class="feed-tools">
        <input id="search-input" class="search-field" type="search" maxlength="100" placeholder="Search titles and stories…" aria-label="Search posts">
        <label class="sort-control" for="sort-select"><span>Sort</span>
          <select id="sort-select" class="select-field">
            <option value="">Newest published</option>
            <option value="title-asc">Title, A–Z</option>
            <option value="title-desc">Title, Z–A</option>
            <option value="modified-desc">Updated, newest</option>
            <option value="modified-asc">Updated, oldest</option>
          </select>
        </label>
      </div>
      <p id="result-count" class="result-count" aria-live="polite"></p>
      <div id="post-list" class="post-list" aria-live="polite"><p class="loading-message">Gathering stories…</p></div>
    </section>`;
  const searchInput = document.getElementById('search-input');
  const sortSelect = document.getElementById('sort-select');
  let debounce;
  const refresh = () => loadFeed(searchInput.value, sortSelect.value);
  searchInput.addEventListener('input', () => {
    clearTimeout(debounce);
    debounce = setTimeout(refresh, 160);
  });
  sortSelect.addEventListener('change', refresh);
  loadFeed('', '');
}

async function loadFeed(query, sort) {
  const list = document.getElementById('post-list');
  if (!list) return;
  const params = new URLSearchParams();
  if (query.trim()) params.set('q', query.trim());
  if (sort) params.set('sort', sort);
  list.innerHTML = '<p class="loading-message">Gathering stories…</p>';
  try {
    const { posts } = await api(`/api/posts${params.size ? `?${params}` : ''}`);
    if (!posts.length) {
      list.innerHTML = '<div class="empty-state"><strong>No blogs found</strong><span>Try another search, or be the first to write.</span></div>';
      document.getElementById('result-count').textContent = '';
      return;
    }
    document.getElementById('result-count').textContent = `${posts.length} ${posts.length === 1 ? 'story' : 'stories'}`;
    list.innerHTML = posts.map(post => {
      const preview = Array.from(post.content).slice(0, 220).join('');
      return `<article class="post-card">
        <h2><a href="/posts/${encodeURIComponent(post.id)}">${escapeHtml(post.title)}</a></h2>
        <div class="post-meta">By ${escapeHtml(post.author)} <span aria-hidden="true">·</span> ${escapeHtml(dateLabel(post))}</div>
        <p class="post-preview">${escapeHtml(preview)}${Array.from(post.content).length > 220 ? '…' : ''}</p>
      </article>`;
    }).join('');
  } catch (error) {
    list.innerHTML = '';
    showError(list, error.message);
  }
}

function renderAuth(register) {
  const title = register ? 'Make yourself at home.' : 'Good to have you back.';
  const description = register ? 'Create an account to add your voice to the conversation.' : 'Log in to keep writing and managing your posts.';
  appRoot.innerHTML = `<section class="auth-card">
    <p class="eyebrow">${register ? 'Join the community' : 'Welcome back'}</p>
    <h1>${title}</h1><p>${description}</p>
    <form id="auth-form" novalidate>
      ${register ? `<label class="form-field"><span>Username</span><input name="username" autocomplete="username" minlength="3" maxlength="30" required pattern="[A-Za-z0-9_]{3,30}"><small class="field-hint">3–30 letters, numbers, or underscores.</small></label>
      <label class="form-field"><span>Email</span><input name="email" type="email" autocomplete="email" maxlength="254" required></label>` : ''}
      ${register ? '' : '<label class="form-field"><span>Username or email</span><input name="identity" autocomplete="username" maxlength="254" required></label>'}
      <label class="form-field"><span>Password</span><input name="password" type="password" autocomplete="${register ? 'new-password' : 'current-password'}" maxlength="256" required>${register ? '<small class="field-hint">12–128 characters.</small>' : ''}</label>
      <button class="button button-primary auth-submit" type="submit">${register ? 'Create account' : 'Log in'}</button>
    </form>
    <p class="auth-switch">${register ? 'Already have an account?' : 'New to Still?'} <a class="text-link" href="${register ? '/login' : '/register'}">${register ? 'Log in' : 'Create an account'}</a></p>
  </section>`;

  const form = document.getElementById('auth-form');
  form.addEventListener('input', event => {
    event.target.removeAttribute('aria-invalid');
    if (event.target.name === 'password') event.target.setCustomValidity('');
  });
  form.addEventListener('submit', async event => {
    event.preventDefault();
    clearError(form);
    const passwordInput = form.elements.namedItem('password');
    const passwordLength = codePointLength(passwordInput.value);
    passwordInput.setCustomValidity(
      passwordLength > 128 || (register && passwordLength < 12)
        ? register ? 'Use a password between 12 and 128 characters.' : 'Password must be no more than 128 characters.'
        : ''
    );
    if (!form.reportValidity()) return;
    const values = Object.fromEntries(new FormData(form));
    const endpoint = register ? '/api/auth/register' : '/api/auth/login';
    try {
      await api(endpoint, { method: 'POST', body: JSON.stringify(values) });
      window.location.assign(register ? '/login' : '/');
    } catch (error) {
      showError(form, error.message);
      applyFieldErrors(form, error.fields);
    }
  });
}

async function renderPost(id) {
  appRoot.innerHTML = '<p class="loading-message">Opening story…</p>';
  try {
    const { post } = await api(`/api/posts/${encodeURIComponent(id)}`);
    const owner = currentUser && currentUser.id === post.authorId;
    appRoot.innerHTML = `<article class="post-detail">
      <a class="back-link" href="/">← All stories</a>
      <p class="eyebrow">A story by ${escapeHtml(post.author)}</p>
      <h1>${escapeHtml(post.title)}</h1>
      <p class="detail-meta">${escapeHtml(dateLabel(post))}</p>
      <div class="detail-content">${escapeHtml(post.content)}</div>
      ${owner ? `<div class="post-actions"><a class="button button-quiet" href="/posts/${encodeURIComponent(post.id)}/edit">Edit post</a><button class="button button-danger" id="delete-post" type="button">Delete post</button></div>` : ''}
    </article>`;
    if (owner) {
      document.getElementById('delete-post').addEventListener('click', () => {
        deleteDialog.returnValue = 'cancel';
        deleteDialog.showModal();
        confirmDeleteButton.onclick = event => {
          event.preventDefault();
          deleteDialog.close('confirm');
        };
        deleteDialog.addEventListener('close', async function onClose() {
          deleteDialog.removeEventListener('close', onClose);
          if (deleteDialog.returnValue !== 'confirm') return;
          try {
            await api(`/api/posts/${encodeURIComponent(post.id)}`, { method: 'DELETE' });
            window.location.assign('/');
          } catch (error) {
            appRoot.prepend(Object.assign(document.createElement('p'), {
              className: 'form-error', role: 'alert', textContent: error.message
            }));
          }
        });
      });
    }
  } catch (error) {
    appRoot.innerHTML = `<section class="empty-state"><strong>Story not found</strong><span>${escapeHtml(error.message)}</span><p><a class="text-link" href="/">Return to the feed</a></p></section>`;
  }
}

async function renderEditor(id, isNew) {
  if (!currentUser) {
    window.location.replace('/login');
    return;
  }
  let post = null;
  if (!isNew) {
    try {
      ({ post } = await api(`/api/posts/${encodeURIComponent(id)}`));
      if (post.authorId !== currentUser.id) {
        appRoot.innerHTML = '<section class="empty-state"><strong>This is not your story to edit.</strong><p><a class="text-link" href="/">Return to the feed</a></p></section>';
        return;
      }
    } catch (error) {
      appRoot.innerHTML = `<section class="empty-state"><strong>Story not found</strong><span>${escapeHtml(error.message)}</span></section>`;
      return;
    }
  }
  appRoot.innerHTML = `<section class="editor-card">
    <p class="eyebrow">${isNew ? 'Put it into words' : 'Make it just right'}</p>
    <h1>${isNew ? 'Write a story.' : 'Edit your story.'}</h1>
    <p>Keep it simple. Say what you mean.</p>
    <form id="post-form" novalidate>
      <label class="form-field"><span>Title</span><input name="title" maxlength="120" required value="${escapeHtml(post ? post.title : '')}"></label>
      <label class="form-field"><span>Your story</span><textarea name="content" maxlength="10000" required>${escapeHtml(post ? post.content : '')}</textarea><small class="field-hint">Up to 10,000 characters.</small></label>
      <div class="editor-actions"><button class="button button-primary" type="submit">${isNew ? 'Publish story' : 'Save changes'}</button><a class="text-link" href="${post ? `/posts/${encodeURIComponent(post.id)}` : '/'}">Cancel</a></div>
    </form>
  </section>`;
  const form = document.getElementById('post-form');
  form.addEventListener('input', event => event.target.removeAttribute('aria-invalid'));
  form.addEventListener('submit', async event => {
    event.preventDefault();
    clearError(form);
    if (!form.reportValidity()) return;
    const body = JSON.stringify(Object.fromEntries(new FormData(form)));
    try {
      const result = await api(isNew ? '/api/posts' : `/api/posts/${encodeURIComponent(id)}`, {
        method: isNew ? 'POST' : 'PATCH', body
      });
      window.location.assign(`/posts/${encodeURIComponent(result.post.id)}`);
    } catch (error) {
      showError(form, error.message);
      applyFieldErrors(form, error.fields);
    }
  });
}

async function boot() {
  try {
    const result = await api('/api/auth/session');
    currentUser = result.user;
  } catch {
    currentUser = null;
  }
  updateNavigation();
  const pathname = decodeURI(window.location.pathname);
  if (pathname === '/register') return renderAuth(true);
  if (pathname === '/login') return renderAuth(false);
  if (pathname === '/posts/new') return renderEditor(null, true);
  const editMatch = pathname.match(/^\/posts\/([^/]+)\/edit$/);
  if (editMatch) return renderEditor(editMatch[1], false);
  const postMatch = pathname.match(/^\/posts\/([^/]+)$/);
  if (postMatch) return renderPost(postMatch[1]);
  renderHome();
}

boot();
